`default_nettype none

// sync_fifo: single-clock FIFO, first-word fall-through.
// Implements interface_spec.md per microarchitecture.md.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer PW    = $clog2(DEPTH);
    localparam integer CW    = $clog2(DEPTH + 1);
    localparam integer LASTI = DEPTH - 1;
    localparam integer ONEI  = 1;

    localparam [PW-1:0] LAST    = LASTI[PW-1:0];
    localparam [PW-1:0] PONE    = ONEI[PW-1:0];
    localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];
    localparam [CW-1:0] CONE    = ONEI[CW-1:0];

    // Storage: datapath, not reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    reg [PW-1:0] wr_ptr_q;
    reg [PW-1:0] wr_ptr_d;
    reg [PW-1:0] rd_ptr_q;
    reg [PW-1:0] rd_ptr_d;
    reg [CW-1:0] count_q;
    reg [CW-1:0] count_d;

    wire wr_acc;
    wire rd_acc;

    // Flags are compares on the count register.
    assign full    = (count_q == DEPTH_C);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;

    // Flags gate the requests: overflow and underflow policy.
    assign wr_acc  = wr_en && !full;
    assign rd_acc  = rd_en && !empty;

    // First-word fall-through read of the oldest slot.
    assign rd_data = mem[rd_ptr_q];

    // Next-state logic.
    always @(*) begin
        wr_ptr_d = wr_ptr_q;
        rd_ptr_d = rd_ptr_q;
        count_d  = count_q;

        if (wr_acc) begin
            if (wr_ptr_q == LAST) begin
                wr_ptr_d = {PW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr_q + PONE;
            end
        end

        if (rd_acc) begin
            if (rd_ptr_q == LAST) begin
                rd_ptr_d = {PW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr_q + PONE;
            end
        end

        case ({wr_acc, rd_acc})
            2'b10:   count_d = count_q + CONE;
            2'b01:   count_d = count_q - CONE;
            default: count_d = count_q;
        endcase
    end

    // State registers, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {PW{1'b0}};
            rd_ptr_q <= {PW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            wr_ptr_q <= wr_ptr_d;
            rd_ptr_q <= rd_ptr_d;
            count_q  <= count_d;
        end
    end

    // Storage write, only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr_q] <= wr_data;
        end
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    integer f_wr_expect;
    always @(*) begin
        f_wr_expect = rd_ptr_q + count_q;
        if (f_wr_expect >= DEPTH) f_wr_expect = f_wr_expect - DEPTH;
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (count_q <= DEPTH_C);
            assert (wr_ptr_q <= LAST);
            assert (rd_ptr_q <= LAST);
            assert (full == (count_q == DEPTH_C));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (wr_ptr_q == f_wr_expect[PW-1:0]);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr_q == {PW{1'b0}});
                assert (rd_ptr_q == {PW{1'b0}});
            end else begin
                if ($past(wr_acc) && !$past(rd_acc)) assert (count_q == $past(count_q) + CONE);
                if (!$past(wr_acc) && $past(rd_acc)) assert (count_q == $past(count_q) - CONE);
                if ($past(wr_acc) == $past(rd_acc)) assert (count_q == $past(count_q));
                if ($past(wr_en) && $past(full)) assert (wr_ptr_q == $past(wr_ptr_q));
                if ($past(rd_en) && $past(empty)) assert (rd_ptr_q == $past(rd_ptr_q));
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
