// sync_fifo_tb: self-checking testbench for sync_fifo.
// Two FIFOs on the same stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12.
module sync_fifo_tb;

    localparam integer D1 = 8;
    localparam integer D2 = 5;

    reg        clk;
    reg        rst_n;
    reg        wr_en;
    reg        rd_en;
    reg [11:0] wr_data;

    wire        full1;
    wire        empty1;
    wire [7:0]  rd_data1;
    wire [3:0]  count1;

    wire        full2;
    wire        empty2;
    wire [11:0] rd_data2;
    wire [2:0]  count2;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) u_fifo8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[7:0]),
        .full    (full1),
        .rd_en   (rd_en),
        .rd_data (rd_data1),
        .empty   (empty1),
        .count   (count1)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) u_fifo5 (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full2),
        .rd_en   (rd_en),
        .rd_data (rd_data2),
        .empty   (empty2),
        .count   (count2)
    );

    // Reference models.
    reg [7:0]  m1_mem [0:7];
    reg [11:0] m2_mem [0:4];
    integer    m1_head, m1_tail, m1_cnt;
    integer    m2_head, m2_tail, m2_cnt;
    reg        m1_seen_full, m2_seen_full;
    reg        a_wr, a_rd;

    // Coverage: 0 full, 1 write while full, 2 drain to empty after full,
    // 3 read while empty, 4 wr+rd empty, 5 wr+rd full, 6 wr+rd between,
    // 7 write pointer wrap, 8 read pointer wrap, 9 reset during traffic.
    integer cov1 [0:9];
    integer cov2 [0:9];

    integer passed, failed, cyc;
    integer i, k, phase;
    reg [31:0] lfsr;
    reg [7:0]  wthr, rthr;
    reg        w, rr, r;
    reg [8*64-1:0] nonce;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task next_rand;
        begin
            lfsr = lfsr ^ (lfsr << 13);
            lfsr = lfsr ^ (lfsr >> 17);
            lfsr = lfsr ^ (lfsr << 5);
        end
    endtask

    task check;
        input         ok;
        input integer id;
        begin
            if (ok === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("sync_fifo_tb: check %0d failed at cycle %0d", id, cyc);
            end
        end
    endtask

    task model1;
        begin
            if (!rst_n) begin
                if (m1_cnt != 0 && (wr_en || rd_en)) cov1[9] = cov1[9] + 1;
                m1_head = 0;
                m1_tail = 0;
                m1_cnt  = 0;
                m1_seen_full = 1'b0;
            end else begin
                a_wr = wr_en && (m1_cnt != D1);
                a_rd = rd_en && (m1_cnt != 0);
                if (m1_cnt == D1) cov1[0] = cov1[0] + 1;
                if (wr_en && m1_cnt == D1) cov1[1] = cov1[1] + 1;
                if (a_rd && m1_cnt == 1 && m1_seen_full) cov1[2] = cov1[2] + 1;
                if (rd_en && m1_cnt == 0) cov1[3] = cov1[3] + 1;
                if (wr_en && rd_en && m1_cnt == 0) cov1[4] = cov1[4] + 1;
                if (wr_en && rd_en && m1_cnt == D1) cov1[5] = cov1[5] + 1;
                if (wr_en && rd_en && m1_cnt > 0 && m1_cnt < D1) cov1[6] = cov1[6] + 1;
                if (a_wr && m1_tail == D1 - 1) cov1[7] = cov1[7] + 1;
                if (a_rd && m1_head == D1 - 1) cov1[8] = cov1[8] + 1;
                if (m1_cnt == D1) m1_seen_full = 1'b1;
                if (a_wr) begin
                    m1_mem[m1_tail[2:0]] = wr_data[7:0];
                    m1_tail = (m1_tail + 1) % D1;
                end
                if (a_rd) begin
                    m1_head = (m1_head + 1) % D1;
                end
                if (a_wr && !a_rd) begin
                    m1_cnt = m1_cnt + 1;
                end else if (a_rd && !a_wr) begin
                    m1_cnt = m1_cnt - 1;
                end
                if (m1_cnt == 0) m1_seen_full = 1'b0;
            end
        end
    endtask

    task model2;
        begin
            if (!rst_n) begin
                if (m2_cnt != 0 && (wr_en || rd_en)) cov2[9] = cov2[9] + 1;
                m2_head = 0;
                m2_tail = 0;
                m2_cnt  = 0;
                m2_seen_full = 1'b0;
            end else begin
                a_wr = wr_en && (m2_cnt != D2);
                a_rd = rd_en && (m2_cnt != 0);
                if (m2_cnt == D2) cov2[0] = cov2[0] + 1;
                if (wr_en && m2_cnt == D2) cov2[1] = cov2[1] + 1;
                if (a_rd && m2_cnt == 1 && m2_seen_full) cov2[2] = cov2[2] + 1;
                if (rd_en && m2_cnt == 0) cov2[3] = cov2[3] + 1;
                if (wr_en && rd_en && m2_cnt == 0) cov2[4] = cov2[4] + 1;
                if (wr_en && rd_en && m2_cnt == D2) cov2[5] = cov2[5] + 1;
                if (wr_en && rd_en && m2_cnt > 0 && m2_cnt < D2) cov2[6] = cov2[6] + 1;
                if (a_wr && m2_tail == D2 - 1) cov2[7] = cov2[7] + 1;
                if (a_rd && m2_head == D2 - 1) cov2[8] = cov2[8] + 1;
                if (m2_cnt == D2) m2_seen_full = 1'b1;
                if (a_wr) begin
                    m2_mem[m2_tail[2:0]] = wr_data;
                    m2_tail = (m2_tail + 1) % D2;
                end
                if (a_rd) begin
                    m2_head = (m2_head + 1) % D2;
                end
                if (a_wr && !a_rd) begin
                    m2_cnt = m2_cnt + 1;
                end else if (a_rd && !a_wr) begin
                    m2_cnt = m2_cnt - 1;
                end
                if (m2_cnt == 0) m2_seen_full = 1'b0;
            end
        end
    endtask

    task check_all;
        begin
            check(full1  === (m1_cnt == D1), 1);
            check(empty1 === (m1_cnt == 0), 2);
            check({28'd0, count1} === m1_cnt, 3);
            check(!((full1 === 1'b1) && (empty1 === 1'b1)), 4);
            if (m1_cnt != 0) check(rd_data1 === m1_mem[m1_head[2:0]], 5);

            check(full2  === (m2_cnt == D2), 11);
            check(empty2 === (m2_cnt == 0), 12);
            check({29'd0, count2} === m2_cnt, 13);
            check(!((full2 === 1'b1) && (empty2 === 1'b1)), 14);
            if (m2_cnt != 0) check(rd_data2 === m2_mem[m2_head[2:0]], 15);
        end
    endtask

    // One clock: drive inputs (at negedge), update models at posedge,
    // check DUT outputs at the following negedge.
    task cycle;
        input        rv;
        input        wv;
        input        rdv;
        input [11:0] dv;
        begin
            rst_n   = rv;
            wr_en   = wv;
            rd_en   = rdv;
            wr_data = dv;
            @(posedge clk);
            model1;
            model2;
            @(negedge clk);
            cyc = cyc + 1;
            check_all;
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        cyc    = 0;
        m1_head = 0; m1_tail = 0; m1_cnt = 0; m1_seen_full = 1'b0;
        m2_head = 0; m2_tail = 0; m2_cnt = 0; m2_seen_full = 1'b0;
        a_wr = 1'b0;
        a_rd = 1'b0;
        for (k = 0; k < 10; k = k + 1) begin
            cov1[k[3:0]] = 0;
            cov2[k[3:0]] = 0;
        end
        lfsr    = 32'h1234_5678;
        rst_n   = 1'b0;
        wr_en   = 1'b0;
        rd_en   = 1'b0;
        wr_data = 12'h000;

        // Reset with requests active: requests are ignored.
        cycle(1'b0, 1'b1, 1'b1, 12'h0a5);
        cycle(1'b0, 1'b1, 1'b0, 12'h05a);
        cycle(1'b0, 1'b0, 1'b0, 12'h000);

        // Read while empty: ignored.
        cycle(1'b1, 1'b0, 1'b1, 12'h000);
        cycle(1'b1, 1'b0, 1'b1, 12'h000);

        // Write and read together when empty: only the write is accepted.
        cycle(1'b1, 1'b1, 1'b1, 12'h3c1);
        cycle(1'b1, 1'b0, 1'b1, 12'h000);

        // Fill past full: writes while full are dropped.
        for (i = 0; i < 10; i = i + 1) begin
            next_rand;
            cycle(1'b1, 1'b1, 1'b0, lfsr[11:0]);
        end

        // Write and read together when full, then in between.
        next_rand;
        cycle(1'b1, 1'b1, 1'b1, lfsr[11:0]);
        next_rand;
        cycle(1'b1, 1'b1, 1'b1, lfsr[11:0]);

        // Drain past empty.
        for (i = 0; i < 12; i = i + 1) begin
            cycle(1'b1, 1'b0, 1'b1, 12'h000);
        end

        // In between: a few writes, then simultaneous write and read.
        for (i = 0; i < 3; i = i + 1) begin
            next_rand;
            cycle(1'b1, 1'b1, 1'b0, lfsr[11:0]);
        end
        for (i = 0; i < 6; i = i + 1) begin
            next_rand;
            cycle(1'b1, 1'b1, 1'b1, lfsr[11:0]);
        end

        // Reset during traffic.
        for (i = 0; i < 2; i = i + 1) begin
            next_rand;
            cycle(1'b1, 1'b1, 1'b0, lfsr[11:0]);
        end
        next_rand;
        cycle(1'b0, 1'b1, 1'b1, lfsr[11:0]);
        next_rand;
        cycle(1'b0, 1'b1, 1'b1, lfsr[11:0]);

        // Random traffic with changing bias and occasional resets.
        for (i = 0; i < 4000; i = i + 1) begin
            phase = (i / 250) % 4;
            case (phase)
                0:       begin wthr = 8'd200; rthr = 8'd70;  end
                1:       begin wthr = 8'd70;  rthr = 8'd200; end
                2:       begin wthr = 8'd128; rthr = 8'd128; end
                default: begin wthr = 8'd240; rthr = 8'd240; end
            endcase
            next_rand;
            w  = (lfsr[7:0]  < wthr);
            rr = (lfsr[15:8] < rthr);
            r  = !(((i % 997) == 500) || ((i % 997) == 501));
            cycle(r, w, rr, lfsr[27:16]);
        end

        // Coverage: every corner case must have been reached.
        for (k = 0; k < 10; k = k + 1) begin
            check(cov1[k[3:0]] != 0, 100 + k);
            check(cov2[k[3:0]] != 0, 200 + k);
        end

        nonce = {64{8'h00}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {64{8'h00}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
